#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=1;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_blurBuf;
float4 amzSample_blurBuf(float2 uv) { return float4(amzt_blurBuf.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_blurBuf(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_progress;
uniform float amzp_radius;
uniform float amzp_angle;
uniform float amzp_alpha;
uniform float amzp_strength;
layout(color) uniform half4 amzp_backColor;
uniform float amzp_backAlpha;
uniform float amzp_backBlendMode;
layout(color) uniform half4 amzp_shineColor;
uniform float amzp_shineAlpha;
uniform float amzp_shineSpec;
uniform float amzp_shineBlendMode;
layout(color) uniform half4 amzp_dropShadowColor;
uniform float amzp_dropShadowAlpha;
uniform float amzp_softDropShadow;
layout(color) uniform half4 amzp_frontShadowColor;
uniform float amzp_frontShadowAlpha;
uniform float amzp_frontShadowBlendMode;
        float2x2 rot2(float a) {
            float c = cos(a);
            float s = sin(a);
            return float2x2(c,s,-s,c);
        }
        float2 l2s( float2 v ) {
            return (float4(v,0.,1.)*amzLayerToScreen()).xy;
        }
        float4 composite(float4 a, float4 b) {
            return a * (1.-b.a) + b;
        }
        float2 curlFun(float t, float maxt, float3 cyl) {
            float2 ret = float2(t, 1.0);
            if (t < (cyl.z) - amzp_radius)
                return ret;
            if (t > (cyl.z) + amzp_radius)
                return float2(-1.0);
            float a = asin((t - (cyl.z)) / amzp_radius);
            float ca = -a + 3.141592;
            ret.x = (cyl.z) + ca * amzp_radius;
            ret.y = cos(ca);
            if (ret.x < maxt)
                return ret;
            if (t < (cyl.z))
                return float2(t, 1.0);
            ret.y = cos(a);
            ret.x = (cyl.z) + a * amzp_radius;
            return ret.x < maxt ? ret : float2(-1.0);
        }
        float2 curlFunFront(float t, float maxt, float3 cyl) {
            float2 ret = float2(t, 1.0);
            if (t < (cyl.z) - amzp_radius)
                return ret;
            if (t > (cyl.z) + amzp_radius)
                return float2(-1.0);
            float a = asin((t - (cyl.z)) / amzp_radius);
            float ca = -a + 3.141592;
            ret.x = (cyl.z) + ca * amzp_radius;
            ret.y = cos(ca);
            if (t < (cyl.z))
                return float2(t, 1.0);
            ret.y = cos(a);
            ret.x = (cyl.z) + a * amzp_radius;
            return ret.x < maxt ? ret : float2(-1.0);
        }
        float4 blendColor( float4 base, float4 color, int mode, float p) {
            if( mode == 1 ) {
                float3 aa = base.rgb / max(base.a,0.00001);
                float3 bb = color.rgb / max(color.a,0.00001);
                float3 cc = aa * bb;
                float4 adjColor = float4(cc,1.) * color.a * p;
                return base * (1.-adjColor.a) + adjColor;
            } else if( mode == 2 ) {
                float3 aa = base.rgb / max(base.a,0.00001);
                float3 bb = color.rgb / max(color.a,0.00001);
                float3 cc = 1.-((1.-aa) * (1.-bb));
                float4 adjColor = float4(cc,1.) * color.a * p;
                return base * (1.-adjColor.a) + adjColor;
            } else {
                float4 adjColor = color * p;
                return base * (1.-adjColor.a) + adjColor;
            }
        }
        void amzRender() {
            float2 uv = amzLayerNorm();
            float2 ur = float2(1.0);
            float h = sqrt(tan(3.141592/4.-abs(mod(amzp_angle*0.0174533,3.141592/2.)-3.141592/4.))+1.);
            float d = (1.-amzp_progress) * h;
            d = 1.-((1.0-d) * (1.+amzp_radius));
            float2 cd = float2(1.0,0.0)*rot2(amzp_angle*0.0174533);
            float2 iv = step(cd,float2(0.));
            uv = iv + uv * (1.-iv*2.);
            float3 cyl = float3(abs(cd),d);
            d = dot(uv, cyl.xy);
            float2 end = abs((ur - uv) / cyl.xy);
            float maxt = d + min(end.x, end.y);
            float2 cff = curlFunFront(d, maxt, cyl);
            float2 cf = curlFun(d, maxt, cyl);
            float2 tuv = uv + cyl.xy * (cf.x - d);
            float2 tuvf = uv + cyl.xy * (cff.x - d);
            tuv /= ur;
            tuv = iv + tuv * (1.-iv*2.);
            tuvf /= ur;
            tuvf = iv + tuvf * (1.-iv*2.);
            float shadow = 1.0 - smoothstep (0.0, amzp_radius * 2.0, -(d - (cyl.z)));
            shadow *= (smoothstep(-amzp_radius, amzp_radius, (maxt - (cf.x + 1.5 * 3.141592 * amzp_radius + amzp_radius))));
            float4 texColor = amzTexture(0,amzScreenNorm());
            float4 blurColor = amzTexture(1,amzScreenNorm());
            float4 frontColor = amzTexture(0,l2s(tuvf));
            float4 result = amzTexture(0,l2s(tuv));
            float4 front = blendColor(frontColor, amzp_frontShadowColor * amzp_frontShadowAlpha * frontColor.a, int(amzp_frontShadowBlendMode), saturate(1.0 - cff.y) );
            result = cf.y > 0.0
                ? front
                : blendColor(
                    blendColor(
                        composite(front,mix(texColor * (1.-blurColor.a)+blurColor,result,amzp_alpha)),
                        amzp_backColor * amzp_backAlpha * result.a, int(amzp_backBlendMode), 1. * step(uv.x,1.) * step(uv.y,1.)
                    ),
                    amzp_shineColor * amzp_shineAlpha * result.a, int(amzp_shineBlendMode), pow(-cf.y,amzp_shineSpec) * step(uv.x,1.) * step(uv.y,1.)
                );
            shadow = smoothstep (0.0, amzp_radius * 2.0, (d - (cyl.z)));
            if((amzp_softDropShadow>0.5)) {
                shadow = saturate((1.-shadow)*2.) * (1.-pow(length(amzLayerNorm()-0.5)*2.,2.) );
                float4 adjShadowColor = amzp_dropShadowColor * amzp_dropShadowAlpha * shadow * (smoothstep(0.5,1.0,blurColor.a)) * texColor.a;
                amzOutput = (cf.x > 0.0 ? composite(adjShadowColor,result) : adjShadowColor) * step(uv.x,1.) * step(uv.y,1.);
            } else {
                amzOutput = (cf.x > 0.0 ? result : amzp_dropShadowColor * amzp_dropShadowAlpha * saturate((1.-shadow)*2.) * texColor.a) * step(uv.x,1.) * step(uv.y,1.);
            }
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

